def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my_last, opp_last = history[-1]

    opp_c = 0
    opp_d = 0
    my_d = 0
    cd = 0
    dd = 0
    ret = 0
    unpun = 0
    repaired = False

    recent_start = n - 10
    if recent_start < 0:
        recent_start = 0

    recent_opp_d = 0
    recent_cd = 0
    recent_my_c = 0

    for i, (m, o) in enumerate(history):
        if o == 'C':
            opp_c += 1
        else:
            opp_d += 1

        if m == 'D':
            my_d += 1

        if m == 'C' and o == 'D':
            cd += 1

        if m == 'D' and o == 'D':
            dd += 1

        if i >= recent_start:
            if o == 'D':
                recent_opp_d += 1
            if m == 'C':
                recent_my_c += 1
            if m == 'C' and o == 'D':
                recent_cd += 1

        if i > 0:
            prev_m = history[i - 1][0]
            if prev_m == 'D':
                if o == 'D':
                    ret += 1
                else:
                    unpun += 1
                if m == 'C' and o == 'C':
                    repaired = True

    if opp_d == 0:
        if repaired:
            return 'D'
        if my_d == 0:
            if n < 5:
                return 'C'
            return 'D'
        if my_last == 'D':
            return 'C'
        return 'C'

    if my_d == 0 and opp_last == 'C' and n >= 5 and n < 90:
        if opp_c * 4 >= n * 3 and cd <= 2:
            return 'D'

    if ret == 0 and unpun >= 1:
        if opp_c * 3 >= n * 2 and cd <= 2:
            return 'D'
        if unpun >= 2 and opp_c * 2 >= n and cd <= 3:
            return 'D'
        if unpun >= 3:
            return 'D'

    if opp_c <= 2 and n >= 8:
        return 'D'

    if recent_cd >= 3:
        return 'D'

    if n >= 90 and recent_opp_d >= 5:
        return 'D'

    if n >= 90 and opp_last == 'D' and history[-2][1] == 'D' and history[-3][1] == 'D':
        return 'D'

    if n >= 20 and opp_d * 2 > n and recent_cd >= 2 and recent_my_c >= 5:
        return 'D'

    if opp_last == 'C':
        return 'C'

    if my_last == 'C':
        if cd <= 1 and opp_c * 3 >= n * 2 and recent_cd <= 1:
            return 'C'
        if cd <= 2 and opp_c * 4 >= n * 3 and recent_cd <= 2:
            return 'C'
        if cd <= 3 and opp_c * 2 >= n and recent_cd <= 1:
            return 'C'
        return 'D'

    if opp_c * 3 >= n * 2 and dd <= 1 and recent_cd == 0:
        return 'C'

    if opp_c * 4 >= n * 3 and dd <= 2 and recent_cd <= 1:
        return 'C'

    if opp_c * 2 >= n and dd <= 4 and recent_opp_d <= 4:
        return 'C'

    return 'D'
